async function fixture(run){const server=await testServer();try{const api=server.agent(),user=(await api('POST','/auth/signup',{name:'Draft owner',email:'draft@example.test',password:'correct-horse-battery'})).data.user,org=(await api('POST','/orgs',{name:'Draft org'})).data.organization,project=(await api('POST','/orgs/'+org.id+'/projects',{key:'DRAFT',name:'Draft project'})).data.project;await run({server,api,user,org,project});}finally{await server.close();}}
test('resolved issue fields preserve independent changes and a later race still rejects without mutation',()=>fixture(async({server,api,project})=>{
  server.ctx.now=()=> '2026-10-16T00:00:00.000Z';
  const baseline=(await api('POST','/projects/'+project.id+'/issues',{title:'Before',description:'Before body',estimate:3})).data.issue,mine={...issueDraftValues(baseline),title:'Mine',description:'',estimate:''};
  const latest=(await api('PATCH','/issues/'+baseline.id,{title:'Peer',priority:4,expectedRevision:baseline.revision})).data.issue;
  const comparison=compareDraft(issueDraftValues(baseline),mine,issueDraftValues(latest));assert.deepEqual(comparison.conflicts.map(field=>field.key),['title']);
  const resolved=issuePayload(resolveDraft(comparison,{title:'mine'})),body={...changedFields(issuePayload(issueForm(latest)),resolved),expectedRevision:latest.revision};
  const newer=(await api('PATCH','/issues/'+baseline.id,{priority:2,expectedRevision:latest.revision})).data.issue,events=[];server.ctx.bus.subscribe(event=>events.push(event));
  const rejected=await api('PATCH','/issues/'+baseline.id,body);assert.equal(rejected.status,409);assert.deepEqual(rejected.data.error.details.current,newer);assert.equal(events.length,0);assert.equal(mine.title,'Mine');
  const next=resolveDraft(compareDraft(issueDraftValues(latest),resolveDraft(comparison,{title:'mine'}),issueDraftValues(newer)));
  const saved=(await api('PATCH','/issues/'+baseline.id,{...changedFields(issuePayload(issueForm(newer)),issuePayload(next)),expectedRevision:newer.revision})).data.issue;
  assert.equal(saved.title,'Mine');assert.equal(saved.description,'');assert.equal(saved.estimate,null);assert.equal(saved.priority,2);assert.equal(saved.updatedAt,baseline.updatedAt);
}));
